  "Check eligibility on mera.pmjay.gov.in or visit any empanelled Govt/Private hospital Arogyamitra Desk.": {
    en: "Check eligibility on mera.pmjay.gov.in or visit any empanelled Govt/Private hospital Arogyamitra Desk.",
    hi: "mera.pmjay.gov.in पर पात्रता जांचें या किसी भी पैनलबद्ध सरकारी/निजी अस्पताल के आरोग्यमित्र डेस्क पर जाएं।",
    ta: "mera.pmjay.gov.in இல் தகுதியைச் சரிபார்க்கவும் அல்லது அரசு/தனியார் மருத்துவமனை ஆரோக்கியமித்ரா மேசையை அணுகவும்.",
    te: "mera.pmjay.gov.in లో అర్హతను తనిఖీ చేయండి లేదా ప్రభుత్వ/ప్రైవేట్ ఆసుపత్రి ఆరోగ్యమిత్ర డెస్క్‌ను సందర్శించండి.",
    ml: "mera.pmjay.gov.in-ൽ യോഗ്യത പരിശോധിക്കുക അല്ലെങ്കിൽ ഏതെങ്കിലും എംപാനൽ ചെയ്ത ആശുപത്രിയിലെ ആരോഗ്യമിത്ര ഡെസ്ക് സന്ദർശിക്കുക.",
    mr: "mera.pmjay.gov.in वर पात्रता तपासा किंवा कोणत्याही पॅनेलवरील सरकारी/खाजगी रुग्णालयातील आरोग्यमित्र कक्षाला भेट द्या.",
    gu: "mera.pmjay.gov.in પર પાત્રતા તપાસો અથવા કોઈપણ પેનલવાળી સરકારી/ખાનગી હોસ્પિટલના આરોગ્યમિત્ર ડેસ્કની મુલાકાત લો."
  },
  "Provide Aadhaar card or Ration card to Arogyamitra for instant e-KYC verification.": {
    en: "Provide Aadhaar card or Ration card to Arogyamitra for instant e-KYC verification.",
    hi: "त्वरित ई-केवाईसी सत्यापन के लिए आरोग्यमित्र को आधार कार्ड या राशन कार्ड प्रदान करें।",
    ta: "உடனடி e-KYC சரிபார்ப்பிற்கு ஆரோக்கியமித்ராவிடம் ஆதார் அட்டை அல்லது ரேஷன் கார்டை வழங்கவும்.",
    te: "తక్షణ e-KYC ధృవీకరణ కోసం ఆరోగ్యమిత్రకు ఆధార్ కార్డు లేదా రేషన్ కార్డును అందించండి.",
    ml: "തൽക്ഷണ ഇ-കെ‌വൈ‌സി പരിശോധനയ്ക്കായി ആരോഗ്യമിത്രയ്ക്ക് ആധാർ കാർഡോ റേഷൻ കാർഡോ നൽകുക.",
    mr: "त्वरित ई-केवायसी पडताळणीसाठी आरोग्यमित्राला आधार कार्ड किंवा रेशन कार्ड द्या.",
    gu: "ત્વરિત e-KYC ચકાસણી માટે આરોગ્યમિત્રને આધાર કાર્ડ અથવા રેશન કાર્ડ આપો."
  },
  "Get Ayushman Card generated instantly.": {
    en: "Get Ayushman Card generated instantly.",
    hi: "तुरंत आयुष्मान कार्ड प्राप्त करें।",
    ta: "உடனடியாக ஆயுஷ்மான் அட்டை பெறவும்.",
    te: "తక్షణమే ఆయుష్మాన్ కార్డును రూపొందించుకోండి.",
    ml: "തൽക്ഷണം ആയുഷ്മാൻ കാർഡ് സ്വന്തമാക്കുക.",
    mr: "त्वरित आयुष्यमान कार्ड मिळवा.",
    gu: "ત્વરિત આયુષ્માન કાર્ડ મેળવો."
  },
  "Visit any nationalized bank, RRB, or Bank Mitra (Business Correspondent).": {
    en: "Visit any nationalized bank, RRB, or Bank Mitra (Business Correspondent).",
    hi: "किसी भी राष्ट्रीयकृत बैंक, आरआरबी या बैंक मित्र से संपर्क करें।",
    ta: "தேசியமயமாக்கப்பட்ட வங்கி, RRB அல்லது பேங்க் மித்ராவை அணுகவும்.",
    te: "ఏదైనా జాతీయం చేయబడిన బ్యాంక్, RRB లేదా బ్యాంక్ మిత్రను సందర్శించండి.",
    ml: "ഏതെങ്കിലും ദേശസാൽകൃത ബാങ്കോ ആർ‌ആർ‌ബിയോ ബാങ്ക് മിത്രയോ സന്ദർശിക്കുക.",
    mr: "कोणत्याही राष्ट्रीयीकृत बँकेला, RRB किंवा बँक मित्राला भेट द्या.",
    gu: "કોઈપણ રાષ્ટ્રીયકૃત બેંક, RRB અથવા બેંક મિત્રની મુલાકાત લો."
  },
  "Fill PMJDY account opening form with Aadhaar eKYC.": {
    en: "Fill PMJDY account opening form with Aadhaar eKYC.",
    hi: "आधार ई-केवाईसी के साथ पीएमजेडीवाई खाता खोलने का फॉर्म भरें।",
    ta: "ஆதார் eKYC உடன் PMJDY கணக்கு தொடக்க படிவத்தை நிரப்பவும்.",
    te: "ఆధార్ eKYC తో PMJDY ఖాతా ప్రారంభ ఫారమ్‌ను పూరించండి.",
    ml: "ആധാർ ഇ-കെ‌വൈ‌സി ഉപയോഗിച്ച് പി‌എം‌ജെഡി‌വൈ അക്കൗണ്ട് തുറക്കൽ ഫോം പൂരിപ്പിക്കുക.",
    mr: "आधार ई-केवायसीसह PMJDY खाते उघडण्याचा अर्ज भरा.",
    gu: "આધાર eKYC સાથે PMJDY ખાતું ખોલવાનું ફોર્મ ભરો."
  },
  "Get zero-balance savings account opened instantly.": {
    en: "Get zero-balance savings account opened instantly.",
    hi: "तुरंत शून्य-शेष बचत खाता खोलें।",
    ta: "உடனடியாக பூஜ்ஜிய இருப்பு சேமிப்புக் கணக்கைத் தொடங்கவும்.",
    te: "తక్షణమే జీరో బ్యాలెన్స్ పొదుపు ఖాతాను పొందండి.",
    ml: "തൽക്ഷണം സീറോ ബാലൻസ് സേവിംഗ്സ് അക്കൗണ്ട് തുറക്കുക.",
    mr: "त्वरित झिरो-बॅलन्स बचत खाते उघडा.",
    gu: "ત્વરિત ઝીરો-બેલેન્સ બચત ખાતું ખોલો."
  },

