  "verifiedCitizenVault": {
    en: "Verified Citizen Document Vault",
    hi: "सत्यापित नागरिक दस्तावेज़ लॉकर",
    ta: "சரிபார்க்கப்பட்ட குடிமக்கள் ஆவண பெட்டகம்",
    te: "ధృవీకరించబడిన పౌర పత్రాల వాల్ట్",
    ml: "സാക്ഷ്യപ്പെടുത്തിയ സിറ്റിസൺ ഡോക്യുമെന്റ് വോൾട്ട്",
    mr: "सत्यापित नागरिक दस्तऐवज वॉल्ट",
    gu: "ચકાસાયેલ નાગરિક દસ્તાવેજ વોલ્ટ"
  },
  "vaultDesc": {
    en: "Securely store official welfare documents. The Rule Engine automatically uses these to verify scheme eligibility.",
    hi: "कल्याणकारी दस्तावेजों को सुरक्षित रखें। नियम इंजन पात्रता सत्यापित करने के लिए स्वचालित रूप से इनका उपयोग करता है।",
    ta: "நலத்திட்ட ஆவணங்களை பாதுகாப்பாக சேமிக்கவும். விதி இயந்திரம் உங்கள் தகுதியை சரிபார்க்க தானாகவே இவற்றைப் பயன்படுத்துகிறது.",
    te: "సంక్షేమ పత్రాలను సురక్షితంగా భద్రపరచండి. పథకం అర్హతను ధృవీకరించడానికి రూల్ ఇంజిన్ వీటిని స్వయంచాలకంగా ఉపయోగిస్తుంది.",
    ml: "ക്ഷേമ രേഖകൾ സുരക്ഷിതമായി സൂക്ഷിക്കുക. റൂൾ എഞ്ചിൻ നിങ്ങളുടെ അർഹത പരിശോധിക്കാൻ ഇവ സ്വയമേവ ഉപയോഗിക്കുന്നു.",
    mr: "कल्याणकारी कागदपत्रे सुरक्षित ठेवा. योजना पात्रता पडताळण्यासाठी नियम इंजिन आपोआप याचा वापर करते.",
    gu: "કલ્યાણકારી દસ્તાવેજો સુરક્ષિત રીતે સંગ્રહિત કરો. નિયમ એન્જિન યોજનાની પાત્રતા ચકાસવા માટે આપમેળે આનો ઉપયોગ કરે છે."
  },
