  "uploadOrScanDocPrompt": {
    en: "Upload or scan this document to unlock schemes requiring {doc} verification.",
    hi: "{doc} सत्यापन की आवश्यकता वाली योजनाओं को अनलॉक करने के लिए इस दस्तावेज़ को अपलोड या स्कैन करें।",
    ta: "{doc} சரிபார்ப்பு தேவைப்படும் திட்டங்களைத் திறக்க இந்த ஆவணத்தை பதிவேற்றவும் அல்லது ஸ்கேன் செய்யவும்.",
    te: "{doc} ధృవీకరణ అవసరమైన పథకాలను అన్‌లాక్ చేయడానికి ఈ పత్రాన్ని అప్‌లోడ్ చేయండి లేదా స్కాన్ చేయండి.",
    ml: "{doc} പരിശോധന ആവശ്യമുള്ള പദ്ധതികൾ അൺലോക്ക് ചെയ്യാൻ ഈ രേഖ അപ്‌ലോഡ് ചെയ്യുകയോ സ്കാൻ ചെയ്യുകയോ ചെയ്യുക.",
    mr: "{doc} पडताळणी आवश्यक असलेल्या योजना अनलॉक करण्यासाठी हे दस्तऐवज अपलोड किंवा स्कॅन करा.",
    gu: "{doc} ચકાસણી જરૂરી હોય તેવી યોજનાઓને અનલૉક કરવા માટે આ દસ્તાવેજ અપલોડ અથવા સ્કેન કરો."
  },
